history.player_before=[&](Integer tick,const StableId& boundary)->Outcome<StableId>{const auto* fact=c.state().facts.find(boundary);if(!fact||tick!=20)return {false,{},common_failure("BadComponentBoundary").error};return {true,"listener",{}};};
history.decision_maker_before=[&](const StableId&,Integer,const StableId& boundary){const auto* fact=c.state().facts.find(boundary);if(fact&&fact->kind=="family_birth_closed"&&fail_close){saw_released=c.count("bag:listener","food",{{Owner::Kind::actor,"listener",{}}}).value==35;return common_failure("InjectedBirthClosureHistoryFailure");}return common_success();};
history.eligible_pair_before=[&](const StableId&,const StableId&,Integer,const StableId& boundary){const auto* fact=c.state().facts.find(boundary);if(fact&&fact->kind=="family_birth_accepted"&&fail_accept){saw_held=c.count("bag:listener","food",{{Owner::Kind::actor,"listener",{}}}).value==5;return common_failure("InjectedBirthPairHistoryFailure");}return common_success();};
auto quote=preview_birth_arrangement_source(c,meeting,interactions,access,family,catalog,"listener","arrangement");check(quote.ok,"actual independent birth node");auto proposal=receive_birth_proposal(c,meeting,interactions,access,family,catalog,state,history,quote.value);check(proposal.ok&&state.replies.empty()&&bag->lots.front().reserved_by.empty(),"heard proposal spent grain or accepted plan");check(!receive_birth_proposal(c,meeting,interactions,access,family,catalog,state,history,quote.value).ok,"duplicate pending proposal admitted");
auto before=encode_common_state(c.state()),before_birth=encode_family_birth(state);fail_accept=true;auto failed=reply_birth_proposal(c,meeting,interactions,access,family,catalog,state,history,proposal.value,"accepted",quote.value);check(!failed.ok&&saw_held,("late validator did not observe actual candidate held food: "+failed.error.original.code).c_str());check(compare_boundary(before,encode_common_state(c.state())).exact()&&compare_boundary(before_birth,encode_family_birth(state)).exact(),"late accepted plan changed Common or domain");fail_accept=false;
